// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(
        address nftToken,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot
    ) public {
        // admissible domain: any non-zero nft address, fee rate within limit
        vm.assume(nftToken != address(0));
        vm.assume(nftToken != address(c));
        feeRate = uint16(bound(feeRate, 0, 5_000));

        vm.deal(address(this), 1 ether);

        bool ok;
        try c.initialize(
            address(0),
            nftToken,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            merkleRoot,
            false,
            false
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any admissible input, initialize succeeds and records
        // the given nft address so that c.nft() reflects it afterwards.
        assertTrue(ok && c.nft() == nftToken);
    }
}
